// Arma el mensaje de WhatsApp a partir del correo de notificacion recibido.
// IMPORTANTE: los patrones de Upwork y Freelancer.com son un punto de partida
// (todavia no vimos un correo real de "respuesta de cliente" de esas dos
// plataformas para confirmar el asunto exacto) -- si llega una alerta que no
// corresponde a una respuesta real, hay que ajustar el query del nodo Gmail
// y/o el filtro de aca abajo.

const out = [];

for (const item of $input.all()) {
  const subject = (item.json.subject || '').toString();
  const from = (item.json.from?.value?.[0]?.address || item.json.from || '').toString();
  const snippet = (item.json.snippet || item.json.textPlain || '').toString();

  let plataforma = 'Desconocida';
  if (from.includes('workana.com')) plataforma = 'Workana';
  else if (from.includes('upwork.com')) plataforma = 'Upwork';
  else if (from.includes('freelancer.com')) plataforma = 'Freelancer';

  // Filtro de seguridad: en Workana descartamos los correos promocionales
  // ("That project was yours...", "New IT & Programming projects...") que
  // NO son un mensaje real de un cliente.
  if (plataforma === 'Workana' && !subject.toLowerCase().includes('new message')) {
    continue;
  }

  const mensaje = `\u{1F4E9} Respuesta de cliente (${plataforma})\n${subject}\n\n${snippet.substring(0, 300)}\n\nRevisa tu correo o la plataforma para el mensaje completo.`;

  out.push({
    json: {
      plataforma,
      asunto: subject,
      mensaje,
    },
  });
}

return out;
